class_name HistoryManager
extends Node

const MAX_ENTRIES: int = 100

var _entries: Array[Dictionary] = []


func add_entry(speaker: String, text: String) -> void:
	var entry_data := {
		"speaker": speaker,
		"text": text
	}
	_entries.append(entry_data)
	if _entries.size() > MAX_ENTRIES:
		_entries.pop_front()


func get_entries() -> Array[Dictionary]:
	return _entries


func clear_history() -> void:
	_entries.clear()

class_name AdvanceController
extends Node

enum AdvanceMode {
	NORMAL,
	AUTO,
	SKIP
}

const CHAR_READ_DELAY: float = 0.05
const MIN_AUTO_DELAY: float = 1.5

var current_mode: AdvanceMode = AdvanceMode.NORMAL
var read_lines: Dictionary = {}


func mark_line_as_read(chapter_path: String, line_index: int) -> void:
	var line_id: String = "%s#%d" % [chapter_path, line_index]
	read_lines[line_id] = true


func is_line_read(chapter_path: String, line_index: int) -> bool:
	var line_id: String = "%s#%d" % [chapter_path, line_index]
	return read_lines.has(line_id)


func calculate_auto_delay(text: String) -> float:
	var delay: float = text.length() * CHAR_READ_DELAY
	return maxf(delay, MIN_AUTO_DELAY)


func should_stop_skip(chapter_path: String, line_index: int, is_choice: bool) -> bool:
	if is_choice:
		return true
	if not is_line_read(chapter_path, line_index):
		return true
	return false

